  "prediction_basis_card_ids": ["C08", "C09", "C01", "C07", "C02", "C20", "C23", "C19", "C26", "C17", "C18", "C04"],
  "claims": [
    {
      "claim": "The query is a permanently charged quaternary pyridinium carbamate; the closest carbamate context, physostigmine, is reported to have poor oral bioavailability, supporting F < 20%.",
      "card_ids": ["C08"]
    },
    {
      "claim": "A charged polar small-molecule context, BMS-187745, had an absolute oral bioavailability of 2.6% in humans, indicating that permanent charge/polarity can drive F well below 20%.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Multiple related low-F contexts remain below 20%: tilidine ~3-7.6%, agomelatine <5%, apocynin <10% in humans and 2.8-8.3% in rats, and aniracetam 8.6-11.4% in rats.",
      "card_ids": ["C01", "C07", "C02", "C20", "C23", "C19", "C26"]
    },
    {
      "claim": "L2 records add direct low absolute/systemic F values (tilidine 7.6±5.3%, apocynin 2.8% and 8.3%, aniracetam 11.4% and 8.6%, agomelatine <5%), reinforcing the low direction.",
      "card_ids": ["C18", "C20", "C23", "C19", "C26", "C17"]
    },
    {
      "claim": "The only near-threshold L2 value, methyl parathion ~20% in rats, is species- and dose-specific and does not outweigh the human <1.7% L1 value or the query's quaternary charge.",
      "card_ids": ["C21", "C04"]
    },
    {
      "claim": "L3 oral AUC/Cmax records concern other molecules (naproxen, rivastigmine, fenofibrate, aspirin, nimesulide, etc.) and report exposure, not absolute bioavailability; they do not provide affirmative threshold-relevant evidence for the query.",
      "card_ids": ["C28", "C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C28", "C29", "C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement is available for the query molecule itself.",
    "No record card exactly matches a quaternary pyridinium carbamate; transfer from physostigmine and BMS-187745 is indirect.",
    "First-pass carbamate hydrolysis and possible active or paracellular absorption of the quaternary ammonium are not characterized in the supplied records.",
    "The property tool reports neutral fraction = 1 despite the formal positive charge in the SMILES, adding uncertainty to the physicochemical prior.",
    "L3 exposure records do not include F values and are for structurally distinct molecules, so they cannot resolve the threshold question."
  ],
  "decision_summary": "Predicted low (F < 20%) because the query is a permanently charged quaternary pyridinium carbamate; the closest carbamate context (physostigmine) reports poor oral bioavailability, a charged polar context (BMS-187745) reports 2.6% absolute F, and multiple related low-F contexts (tilidine, agomelatine, apocynin, aniracetam) remain below 20%. L3 oral AUC/Cmax records are exposure measurements for unrelated molecules and do not change this assessment."
}

